-- Existing aliases that belong to a nutritionally distinct new row are re-pointed at it.
update ingredient_aliases a set ingredient_id = i.id from (values
  ('ancho chile', 'ancho chile'),
  ('whole wheat pasta', 'whole wheat pasta'),
  ('tomato puree', 'tomato puree'),
  ('skim milk', 'skim milk'),
  ('skim milk', 'nonfat milk'),
  ('skim milk', 'fat free milk'),
  ('skim milk', 'fat-free milk'),
  ('skim milk', 'skimmed milk'),
  ('whole milk', 'whole milk'),
  ('reduced fat milk', '2% milk'),
  ('reduced fat milk', 'low-fat milk'),
  ('reduced fat milk', 'low fat milk'),
  ('reduced fat milk', 'semi-skimmed milk'),
  ('whole wheat bread', 'whole wheat bread')
) v(cn, alias) join ingredients i on i.canonical_name = v.cn where a.alias = v.alias;

