-- Variants join their parent's family so a pantry holding "milk" still matches "skim milk".
update ingredients c set family_id = p.id from (values
  ('whole wheat pasta', 'pasta'),
  ('skim milk', 'milk'),
  ('whole milk', 'milk'),
  ('reduced fat milk', 'milk'),
  ('whole wheat bread', 'sandwich bread')
) v(cn, pn) join ingredients p on p.canonical_name = v.pn where c.canonical_name = v.cn and c.family_id is null;
commit;
